const svgArt = (kind, a, b, accent = '#C9A45C') => {
  const patterns = {
    orbit: `<circle cx="640" cy="430" r="250" fill="none" stroke="${accent}" stroke-width="2"/><circle cx="640" cy="430" r="175" fill="${b}" opacity=".35"/><circle cx="510" cy="300" r="28" fill="${accent}"/><path d="M260 660 Q640 90 1020 660" fill="none" stroke="${a}" stroke-width="70" opacity=".42"/>`,
    amber: `<rect x="260" y="95" width="760" height="670" rx="330" fill="${a}" opacity=".66"/><path d="M200 650 C420 420 480 160 1080 220 L1080 730 L200 730Z" fill="${b}"/><circle cx="780" cy="300" r="92" fill="${accent}" opacity=".74"/>`,
    strata: `<path d="M0 640 Q260 400 520 570 T1280 400 V900 H0Z" fill="${a}"/><path d="M0 730 Q330 480 650 650 T1280 500 V900 H0Z" fill="${b}"/><path d="M80 260 H1200 M180 340 H1100" stroke="${accent}" stroke-width="2" opacity=".6"/>`,
    monolith: `<rect x="450" y="100" width="380" height="680" fill="${a}"/><rect x="520" y="170" width="240" height="540" fill="${b}"/><path d="M640 170 V710 M520 440 H760" stroke="${accent}" stroke-width="3"/>`,
    veil: `<path d="M290 760 C390 590 270 290 500 110 C560 430 820 340 990 680 C740 580 600 850 290 760Z" fill="${a}" opacity=".8"/><path d="M390 720 C500 500 390 330 620 190 C630 470 860 420 900 680" fill="none" stroke="${accent}" stroke-width="24" opacity=".7"/>`,
    grid: `<g stroke="${accent}" opacity=".55">${Array.from({length:8},(_,i)=>`<path d="M${220+i*120} 100V800"/>`).join('')}${Array.from({length:6},(_,i)=>`<path d="M160 ${180+i*110}H1120"/>`).join('')}</g><circle cx="640" cy="450" r="220" fill="${a}" opacity=".75"/><rect x="520" y="330" width="240" height="240" fill="${b}"/>`
  };
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1280 900"><rect width="1280" height="900" fill="#111"/><rect x="28" y="28" width="1224" height="844" fill="none" stroke="#2b2b2b"/>${patterns[kind] || patterns.orbit}<text x="64" y="836" fill="#84704b" font-family="serif" font-size="18" letter-spacing="6">DJ ARCHIVE · DEMO</text></svg>`;
  return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(svg)}`;
};

