const siteBase = window.__SITE_BASE__ || '/';
const routePath = siteBase === '/' ? location.pathname : `/${location.pathname.slice(siteBase.length)}`;
const path = routePath.replace(/\/+$/,'') || '/';
const siteUrl = route => siteBase === '/' ? route : `${siteBase}${route.replace(/^\//,'')}`;
const main = document.querySelector('#main');
const artCard = (a, i=0) => `<a class="art-card reveal" style="--delay:${i*.05}s" href="/collection/${a.slug}/"><div class="art-image"><img src="${a.art}" alt="演示作品《${a.title}》的抽象占位图"><span>DEMO</span></div><div class="art-meta"><p>${a.id} · ${a.categoryZh}</p><h3>${a.title}<small>${a.titleEn}</small></h3><p>${a.artist} · ${a.year} · ${a.material}</p></div></a>`;
const sectionTitle = (kicker,title,aside='') => `<header class="section-head"><div><p>${kicker}</p><h2>${title}</h2></div>${aside?`<p>${aside}</p>`:''}</header>`;

function home(){
  main.innerHTML = `<section class="hero"><img src="${artworks[0].art}" alt="演示藏品《静默轨道》局部"><div class="hero-shade"></div><div class="hero-copy"><p class="eyebrow">DJ · PERSONAL COLLECTION MUSEUM</p><h1>收藏艺术，<br>记录时间。</h1><p class="hero-en">ART, OBJECTS<br>& MEMORIES.</p><a class="text-link" href="/collection/">EXPLORE COLLECTION <span>↗</span></a></div><div class="hero-index">01 / 09<br><small>FEATURED WORK · DEMO</small></div><div class="scroll-cue">SCROLL <i></i></div></section>
  <section class="intro wrap">${sectionTitle('01 · ABOUT THE COLLECTION','收藏，是与时间建立关系。')}<div class="intro-grid"><p class="lead">每一件作品，都是一次审美选择，<br>也是一段时间记忆。</p><div><p>这是一座持续生长的私人数字博物馆。它记录艺术、设计与器物，也记录观看如何在不同时间里发生。</p><p class="demo-note">当前馆藏内容为 Demo 演示数据，便于未来替换为真实档案。</p><a class="text-link" href="/about/">READ OUR STORY <span>↗</span></a></div></div></section>
  <section class="categories wrap">${sectionTitle('02 · CATEGORIES','七种路径，进入同一座收藏。','不以类型限定观看，只为档案建立清晰入口。')}<div class="category-list">${['绘画|PAINTING|01|painting','雕塑|SCULPTURE|02|sculpture','摄影|PHOTOGRAPHY|02|photography','装置|INSTALLATION|01|installation','设计收藏|DESIGN OBJECTS|01|design','数字艺术|DIGITAL ART|01|digital','古董|ANTIQUE|01|antique'].map(x=>{let [z,e,n,c]=x.split('|');return `<a href="/collection/?category=${c}"><span>${z}<small>${e}</small></span><b>${n}</b><i>↗</i></a>`}).join('')}</div></section>
  <section class="featured wrap">${sectionTitle('03 · FEATURED WORKS','精选藏品')}<div class="art-grid editorial">${artworks.filter(a=>a.featured).slice(0,6).map(artCard).join('')}</div><a class="outline-link" href="/collection/">VIEW FULL ARCHIVE · 09 WORKS</a></section>
  <section class="timeline wrap">${sectionTitle('04 · TIMELINE','收藏时间轴','演示节点 · 待真实收藏记录替换')}<div class="timeline-track">${[['2020','档案起点','建立第一批器物与作品记录'],['2022','观看的扩展','摄影与抽象绘画进入收藏'],['2024','空间意识','开始关注雕塑与装置'],['2026','数字博物馆','将收藏脉络整理为线上档案']].map((x,i)=>`<article><b>${x[0]}</b><i></i><h3>${x[1]}</h3><p>${x[2]}</p><small>DEMO ${String(i+1).padStart(2,'0')}</small></article>`).join('')}</div></section>
  <section class="exhibition-feature"><img src="${artworks[3].art}" alt="演示展览主视觉"><div><p>ONLINE EXHIBITION · DEMO NO.001</p><h2>关于时间的收藏</h2><h3>MEMORY OF TIME</h3><p>当物件被留下，时间是否获得了另一种形状？</p><a class="text-link" href="/exhibitions/memory-of-time/">ENTER EXHIBITION <span>↗</span></a></div></section>
  <section class="journal-preview wrap">${sectionTitle('05 · JOURNAL','收藏日志')}<div class="journal-list">${journals.map(journalCard).join('')}</div></section>`;
}

function collection(){
  main.innerHTML = `<section class="page-hero wrap"><p>THE COLLECTION · DEMO ARCHIVE</p><h1>藏品库</h1><div><p>一座可检索、可漫游的个人收藏档案。</p><b id="work-count">09 WORKS</b></div></section><section class="archive wrap"><div class="filterbar"><label class="archive-search">⌕<input id="archive-q" type="search" placeholder="搜索作品、艺术家、材料"></label><div class="filters"><button class="active" data-cat="all">全部</button>${[...new Set(artworks.map(a=>a.category))].map(c=>`<button data-cat="${c}">${artworks.find(a=>a.category===c).categoryZh}</button>`).join('')}<button id="clear-filter">清空</button></div><div class="view-toggle" aria-label="视图选择"><button class="active" data-view="editorial">不对称</button><button data-view="regular">网格</button></div></div><div id="archive-grid" class="art-grid editorial"></div><div id="empty" class="empty" hidden><span>∅</span><h2>没有找到相符藏品</h2><p>尝试更换关键词或清空筛选。</p></div></section>`;
  const grid=document.querySelector('#archive-grid'), input=document.querySelector('#archive-q'), count=document.querySelector('#work-count'); let cat=new URLSearchParams(location.search).get('category')||'all';
  function render(){const q=input.value.trim().toLowerCase();const list=artworks.filter(a=>(cat==='all'||a.category===cat)&&[a.title,a.titleEn,a.artist,a.material,a.tags.join(' ')].join(' ').toLowerCase().includes(q));grid.innerHTML=list.map(artCard).join('');count.textContent=`${String(list.length).padStart(2,'0')} WORKS`;document.querySelector('#empty').hidden=!!list.length;document.querySelectorAll('[data-cat]').forEach(b=>b.classList.toggle('active',b.dataset.cat===cat));}
  input.addEventListener('input',()=>{render();syncQuery()});document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{cat=b.dataset.cat;render();syncQuery()});document.querySelector('#clear-filter').onclick=()=>{cat='all';input.value='';render();history.replaceState({},'',siteUrl(path))};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-view]').forEach(x=>x.classList.remove('active'));b.classList.add('active');grid.className=`art-grid ${b.dataset.view}`});function syncQuery(){const p=new URLSearchParams();if(cat!=='all')p.set('category',cat);if(input.value)p.set('q',input.value);history.replaceState({},'',`${siteUrl(path)}${p.size?'?'+p:''}`)}input.value=new URLSearchParams(location.search).get('q')||'';render();
}

function artworkDetail(slug){const a=artworks.find(x=>x.slug===slug)||artworks[0]; const related=artworks.filter(x=>x.slug!==a.slug&&(x.artist===a.artist||x.category===a.category)).slice(0,3); main.innerHTML=`<section class="detail-hero"><button class="zoom-art" aria-label="放大作品"><img src="${a.art}" alt="演示作品《${a.title}》"><span>＋ VIEW FULLSCREEN</span></button><div class="detail-title"><p>${a.id} · DEMO ARCHIVE</p><h1>${a.title}</h1><h2>${a.titleEn}</h2><p>${a.artist} · ${a.year}</p></div></section><section class="details wrap"><div>${sectionTitle('ARTWORK INFORMATION','作品档案')}<dl><div><dt>藏品编号</dt><dd>${a.id}</dd></div><div><dt>创作者</dt><dd><a href="/artists/${a.artistSlug}/">${a.artist} ↗</a></dd></div><div><dt>创作年代</dt><dd>${a.year}</dd></div><div><dt>分类</dt><dd>${a.categoryZh}</dd></div><div><dt>材料</dt><dd>${a.material}</dd></div><div><dt>尺寸</dt><dd>${a.dimensions}</dd></div><div><dt>创作地区</dt><dd>${a.origin}</dd></div><div><dt>收藏时间</dt><dd>${a.acquired} · DEMO</dd></div></dl></div><article class="prose"><p class="eyebrow">CURATORIAL NOTE · DEMO</p><h2>作品解读</h2><p>${a.desc}</p><p>形式并不是终点。材质、尺度与观看距离共同构成作品的节奏，让每一次靠近都成为不同的经验。</p><hr><p class="eyebrow">COLLECTING STORY</p><h2>收藏故事</h2><div class="story-empty"><span>✦</span><p>${a.story||'真实收藏故事尚未填写。这里将保留安静的空白，不以虚构内容替代个人记忆。'}</p></div></article></section><section class="artist-strip wrap"><p>ARTIST PROFILE</p><div><h2>${a.artist}</h2><p>${artists.find(x=>x.slug===a.artistSlug)?.bio||'艺术家资料待补充。'}</p><a class="text-link" href="/artists/${a.artistSlug}/">VIEW ARTIST ARCHIVE <span>↗</span></a></div></section><section class="related wrap">${sectionTitle('RELATED WORKS','相关藏品')}<div class="art-grid regular">${(related.length?related:artworks.slice(1,4)).map(artCard).join('')}</div></section>`; document.querySelector('.zoom-art').onclick=()=>openLightbox(a);
}

const artistCard = (a,i=0)=>{const works=artworks.filter(x=>x.artistSlug===a.slug);return `<a class="artist-card reveal" style="--delay:${i*.05}s" href="/artists/${a.slug}/"><div>${a.name.split('').map(x=>`<span>${x}</span>`).join('')}</div><p>0${works.length} WORK${works.length===1?'':'S'}</p><h2>${a.name}<small>${a.nameEn}</small></h2><p>${a.medium}</p><i>↗</i></a>`};
function artistIndex(){main.innerHTML=`<section class="page-hero wrap"><p>ARTIST INDEX · DEMO ARCHIVE</p><h1>艺术家</h1><div><p>从创作者进入收藏，寻找作品之间的内在联系。</p><b>05 ARTISTS</b></div></section><section class="artist-index wrap"><div class="artist-tools"><input id="artist-q" placeholder="按姓名搜索" aria-label="按姓名搜索"><select id="artist-sort" aria-label="排序"><option value="name">按姓名排序</option><option value="count">按作品数量</option></select></div><div id="artists-grid">${artists.map(artistCard).join('')}</div></section>`;const render=()=>{let list=artists.filter(a=>(a.name+a.nameEn).toLowerCase().includes(document.querySelector('#artist-q').value.toLowerCase()));if(document.querySelector('#artist-sort').value==='count')list.sort((a,b)=>artworks.filter(x=>x.artistSlug===b.slug).length-artworks.filter(x=>x.artistSlug===a.slug).length);document.querySelector('#artists-grid').innerHTML=list.map(artistCard).join('')};document.querySelector('#artist-q').oninput=render;document.querySelector('#artist-sort').onchange=render;}
function artistDetail(slug){const a=artists.find(x=>x.slug===slug)||artists[0],works=artworks.filter(x=>x.artistSlug===a.slug);main.innerHTML=`<section class="artist-hero wrap"><p>ARTIST FILE · DEMO</p><h1>${a.name}</h1><h2>${a.nameEn}</h2><div><span>${a.medium}</span><span>COLLECTED WORKS · ${String(works.length).padStart(2,'0')}</span></div></section><section class="artist-bio wrap"><p class="dropcap">${a.bio}</p><dl><div><dt>主要媒介</dt><dd>${a.medium}</dd></div><div><dt>档案状态</dt><dd>演示资料 · 待核实替换</dd></div></dl></section><section class="wrap">${sectionTitle('WORKS IN THE COLLECTION','馆藏作品')}<div class="art-grid editorial">${works.map(artCard).join('')||'<div class="empty"><p>暂无相关藏品</p></div>'}</div></section>`}

function exhibitions(){main.innerHTML=`<section class="page-hero wrap"><p>ONLINE EXHIBITIONS</p><h1>展览</h1><div><p>以收藏为线索，在屏幕上重新组织观看。</p><b>01 CURRENT · DEMO</b></div></section><section class="ex-list wrap"><a href="/exhibitions/memory-of-time/" class="ex-card"><img src="${artworks[3].art}" alt="关于时间的收藏展览封面"><span>NOW · DEMO</span><div><p>NO.001</p><h2>关于时间的收藏</h2><h3>MEMORY OF TIME</h3><p>2026.10 — OPEN ENDED</p></div><i>ENTER ↗</i></a><div class="coming"><p>NEXT EXHIBITION</p><h2>档案正在生长</h2><span>CURATION IN PROGRESS · 2027</span></div></section>`}
function exhibitionDetail(){const shown=[artworks[0],artworks[1],artworks[3],artworks[5]];main.innerHTML=`<section class="ex-hero"><img src="${artworks[3].art}" alt="关于时间的收藏演示展览主视觉"><div><p>ONLINE EXHIBITION · DEMO NO.001</p><h1>关于时间的收藏</h1><h2>MEMORY OF TIME</h2><span>2026.10 — OPEN ENDED</span></div></section><section class="curatorial wrap"><p>CURATORIAL TEXT · DEMO</p><h2>物件被收藏之后，<br>时间并没有停止。</h2><div><p>它在材质的变化、观看的重复，以及个人记忆的持续改写中继续向前。展览以四件演示作品构成一条松散的时间路径。</p><p>从轨道、琥珀、暗室到信号系统，四种媒介共同提出一个问题：我们保存的，究竟是物，还是与物相遇的那一刻？</p></div></section><section class="ex-flow">${shown.map((a,i)=>`<article><div class="ex-no">0${i+1}</div><button data-art-link="/collection/${a.slug}/"><img src="${a.art}" alt="演示作品《${a.title}》"></button><div><p>${a.artist} · ${a.year}</p><h2>${a.title}</h2><h3>${a.titleEn}</h3><p>${a.desc}</p></div></article>`).join('')}</section>`;document.querySelectorAll('[data-art-link]').forEach(b=>b.onclick=()=>location.href=siteUrl(b.dataset.artLink))}

function journalCard(j){return `<a class="journal-card" href="/journal/${j.slug}/"><p>${j.date} · ${j.tag}</p><h3>${j.title}</h3><p>${j.excerpt}</p><i>READ ↗</i></a>`}
function journal(){main.innerHTML=`<section class="page-hero wrap"><p>NOTES ON COLLECTING</p><h1>收藏日志</h1><div><p>关于收藏、观看、旅行与艺术的持续记录。</p><b>03 ENTRIES · DEMO</b></div></section><section class="journal-page wrap"><div class="journal-feature"><div><p>${journals[0].date} · ${journals[0].tag}</p><h2>${journals[0].title}</h2><p>${journals[0].excerpt}</p><a class="text-link" href="/journal/${journals[0].slug}/">READ ARTICLE <span>↗</span></a></div><img src="${artworks[1].art}" alt="收藏日志演示封面"></div><div class="journal-list">${journals.slice(1).map(journalCard).join('')}</div></section>`}
function journalDetail(slug='why-we-collect'){const j=journals.find(x=>x.slug===slug)||journals[0];main.innerHTML=`<article class="article wrap"><header><p>COLLECTING ESSAY · DEMO</p><h1>${j.title}</h1><p>${j.date} · 阅读约 4 分钟</p></header><figure><img src="${artworks[1].art}" alt="日志文章演示配图"><figcaption>演示图像 · DJ ARCHIVE</figcaption></figure><div class="article-body"><p class="lead">${j.excerpt}</p><p>起初，我们或许被作品的颜色、形态或触感吸引。但真正让一件作品留下的，往往是某种无法立即言明的共鸣。它可能来自一次旅行、一段对话，或某个需要重新理解自己的时刻。</p><h2>让观看发生得更久</h2><p>博物馆中的相遇有明确的开始与结束，私人空间里的作品却会进入日常。晨光、季节、居住状态不断改变它，而我们也在这种重复中学习如何观看。</p><blockquote>收藏的意义，不在于拥有答案，而在于保存一个愿意反复提出的问题。</blockquote><p>这篇内容为版式与阅读体验而写的演示文章。未来应替换为收藏者本人的真实经历和观点。</p></div><footer><span>标签：${j.tag} / Demo</span><a href="/journal/">← 返回收藏日志</a></footer></article>`}
function about(){main.innerHTML=`<section class="about-hero"><div><p>ABOUT DJ'S COLLECTION</p><h1>一座持续生长的<br>私人收藏档案。</h1><p>An evolving archive of art,<br>objects and memories.</p></div><img src="${artworks[4].art}" alt="演示收藏空间视觉"></section><section class="manifesto wrap"><p>COLLECTING PHILOSOPHY</p><h2>收藏并非占有，<br>而是与时间建立关系。</h2><div class="columns"><p>每一件作品进入收藏，都带来一种新的观看方式。它们并不需要给出相同的答案，却可以在同一空间里彼此回应。</p><p>这座线上博物馆用于整理作品信息、艺术家档案、展览线索与个人记忆。当前内容全部为演示数据，真实简介与收藏方向可从结构化内容中逐步替换。</p></div></section><section class="principles wrap">${sectionTitle('ARCHIVE PRINCIPLES','我们如何记录')}<div>${[['01','尊重作品','保持作品原始比例与色彩，不以统一滤镜改变它。'],['02','事实优先','不虚构来源、价格、证书与收藏故事。'],['03','持续更新','把档案视作长期生长的结构，而不是完成品。']].map(x=>`<article><b>${x[0]}</b><h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div></section><section class="contact wrap"><p>CONTACT</p><h2>联系方式尚未公开</h2><p>提供真实邮箱或社交账号后，此处将自动显示；当前不使用虚假联系信息。</p></section>`}

const routes = [
  [/^\/$/,home],[/^\/collection$/,collection],[/^\/collection\/([^/]+)$/,m=>artworkDetail(m[1])],[/^\/artists$/,artistIndex],[/^\/artists\/([^/]+)$/,m=>artistDetail(m[1])],[/^\/exhibitions$/,exhibitions],[/^\/exhibitions\/memory-of-time$/,exhibitionDetail],[/^\/journal$/,journal],[/^\/journal\/([^/]+)$/,m=>journalDetail(m[1])],[/^\/about$/,about]
];
let matched=false;for(const [rx,fn] of routes){const m=path.match(rx);if(m){fn(m);matched=true;break}}if(!matched){main.innerHTML=`<section class="not-found"><p>404 · ARCHIVE NOT FOUND</p><h1>这一页尚未被收藏</h1><a class="text-link" href="/">RETURN HOME <span>↗</span></a></section>`}

function openLightbox(a){const lb=document.querySelector('.lightbox');lb.querySelector('img').src=a.art;lb.querySelector('img').alt=`演示作品《${a.title}》大图`;lb.querySelector('p').textContent=`${a.title} · ${a.artist} · DEMO`;lb.classList.add('open');lb.setAttribute('aria-hidden','false');document.body.classList.add('locked');lb.querySelector('.lightbox-close').focus()}
function closeLightbox(){const lb=document.querySelector('.lightbox');lb.classList.remove('open');lb.setAttribute('aria-hidden','true');document.body.classList.remove('locked')}
document.querySelector('.lightbox-close').onclick=closeLightbox;document.querySelector('.lightbox').onclick=e=>{if(e.target.classList.contains('lightbox'))closeLightbox()};
const menu=document.querySelector('.menu-toggle');menu.onclick=()=>{const open=document.body.classList.toggle('menu-open');menu.setAttribute('aria-expanded',open)};
const searchPanel=document.querySelector('.search-panel'),searchInput=document.querySelector('#global-search'),searchResults=document.querySelector('#global-results');document.querySelector('.search-trigger').onclick=()=>{searchPanel.classList.add('open');searchPanel.setAttribute('aria-hidden','false');setTimeout(()=>searchInput.focus(),100)};document.querySelector('.panel-close').onclick=closeSearch;function closeSearch(){searchPanel.classList.remove('open');searchPanel.setAttribute('aria-hidden','true')};searchInput.oninput=()=>{const q=searchInput.value.toLowerCase();const list=q?artworks.filter(a=>(a.title+a.titleEn+a.artist+a.material).toLowerCase().includes(q)):[];searchResults.innerHTML=list.length?list.map(a=>`<a href="/collection/${a.slug}/"><span>${a.id}</span><b>${a.title}</b><small>${a.artist} · ${a.year}</small></a>`).join(''):(q?'<p class="no-result">没有找到相符藏品</p>':'<p class="search-hint">输入关键词，在演示档案中搜索</p>')};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeLightbox();closeSearch()}});window.addEventListener('scroll',()=>document.querySelector('#header').classList.toggle('scrolled',scrollY>30));
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="/"]');if(a&&siteBase!=='/'){e.preventDefault();location.href=siteUrl(a.getAttribute('href'))}});
const observer=new IntersectionObserver(es=>es.forEach(e=>e.isIntersecting&&e.target.classList.add('visible')),{threshold:.08});document.querySelectorAll('.reveal,.section-head').forEach(el=>observer.observe(el));

